'use client';

import {
  Collapsible as CollapsiblePrimitive,
  useCollapsible,
  useCollapsibleContext,
} from '@ark-ui/react/collapsible';
import { ark, type HTMLArkProps } from '@ark-ui/react/factory';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef } from 'react';
import { forwardRef } from 'react';
import { ChevronDownIcon } from '@/lib/moduix/icons/ui';
import styles from './Collapsible.module.css';

const Collapsible = forwardRef<
  ComponentRef<typeof CollapsiblePrimitive.Root>,
  ComponentProps<typeof CollapsiblePrimitive.Root>
>(function Collapsible({ className, ...props }, ref) {
  return (
    <CollapsiblePrimitive.Root
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="collapsible-root"
    />
  );
});

const CollapsibleRootProvider = forwardRef<
  ComponentRef<typeof CollapsiblePrimitive.RootProvider>,
  ComponentProps<typeof CollapsiblePrimitive.RootProvider>
>(function CollapsibleRootProvider({ className, ...props }, ref) {
  return (
    <CollapsiblePrimitive.RootProvider
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="collapsible-root-provider"
    />
  );
});

const CollapsibleTrigger = forwardRef<
  ComponentRef<typeof CollapsiblePrimitive.Trigger>,
  ComponentProps<typeof CollapsiblePrimitive.Trigger>
>(function CollapsibleTrigger({ asChild, className, ...props }, ref) {
  return (
    <CollapsiblePrimitive.Trigger
      ref={ref}
      asChild={asChild}
      className={clsx(!asChild && styles.trigger, className)}
      {...props}
      data-slot="collapsible-trigger"
    />
  );
});

const CollapsibleIndicator = forwardRef<
  ComponentRef<typeof CollapsiblePrimitive.Indicator>,
  ComponentProps<typeof CollapsiblePrimitive.Indicator>
>(function CollapsibleIndicator({ className, children, ...props }, ref) {
  return (
    <CollapsiblePrimitive.Indicator
      ref={ref}
      className={clsx(styles.indicator, className)}
      {...props}
      data-slot="collapsible-indicator"
    >
      {children ?? <ChevronDownIcon />}
    </CollapsiblePrimitive.Indicator>
  );
});

const CollapsibleContent = forwardRef<
  ComponentRef<typeof CollapsiblePrimitive.Content>,
  ComponentProps<typeof CollapsiblePrimitive.Content>
>(function CollapsibleContent({ className, ...props }, ref) {
  return (
    <CollapsiblePrimitive.Content
      ref={ref}
      className={clsx(styles.content, className)}
      {...props}
      data-slot="collapsible-content"
    />
  );
});

const CollapsibleBody = forwardRef<ComponentRef<typeof ark.div>, HTMLArkProps<'div'>>(
  function CollapsibleBody({ className, ...props }, ref) {
    return (
      <ark.div
        ref={ref}
        className={clsx(styles.body, className)}
        {...props}
        data-scope="collapsible"
        data-part="body"
        data-slot="collapsible-body"
      />
    );
  },
);

const CollapsibleContext = CollapsiblePrimitive.Context;

export {
  Collapsible,
  CollapsibleBody,
  CollapsibleContent,
  CollapsibleContext,
  CollapsibleIndicator,
  CollapsibleRootProvider,
  CollapsibleTrigger,
  useCollapsible,
  useCollapsibleContext,
};

export type {
  CollapsibleContentProps,
  CollapsibleContextProps,
  CollapsibleIndicatorProps,
  CollapsibleOpenChangeDetails,
  CollapsibleRootProps,
  CollapsibleRootProviderProps,
  CollapsibleTriggerProps,
  UseCollapsibleContext,
  UseCollapsibleProps,
  UseCollapsibleReturn,
} from '@ark-ui/react/collapsible';

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: flex;
    width: 100%;
    min-width: 0;
    flex-direction: column;
    color: var(--moduix-color-foreground);
  }

  .trigger {
    box-sizing: border-box;
    display: flex;
    width: 100%;
    align-items: center;
    justify-content: space-between;
    gap: var(--moduix-collapsible-trigger-gap, var(--moduix-spacing-2));
    margin: 0;
    border: 0;
    padding-block: var(--moduix-collapsible-trigger-padding-y, var(--moduix-spacing-1));
    padding-inline: var(--moduix-collapsible-trigger-padding-x, 0);
    background-color: transparent;
    color: inherit;
    font: inherit;
    font-size: var(--moduix-collapsible-trigger-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-line-height-text-sm);
    text-align: start;
    user-select: none;
    outline: 0;
    cursor: pointer;

    &:focus-visible {
      outline: var(--moduix-focus-ring-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-focus-ring-inset-offset);
    }

    &:is([disabled], [data-disabled]) {
      opacity: var(--moduix-opacity-disabled);
      cursor: default;
    }
  }

  .indicator {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(--moduix-collapsible-indicator-size, var(--moduix-spacing-3));
    height: var(--moduix-collapsible-indicator-size, var(--moduix-spacing-3));
    flex-shrink: 0;
    transition: transform var(--moduix-transition-default);

    & svg {
      width: 100%;
      height: 100%;
    }

    &[data-state='open'] {
      transform: rotate(180deg);
    }
  }

  .content {
    box-sizing: border-box;
    overflow: hidden;
    color: var(--moduix-collapsible-content-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-collapsible-content-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-line-height-text-sm);

    &[data-state='open'] {
      animation: global(moduix-collapsible-content-open) var(--moduix-transition-default);
    }

    &[data-state='closed'] {
      animation: global(moduix-collapsible-content-closed) var(--moduix-transition-default);
    }

    &[data-has-collapsed-size][data-state='open'] {
      animation-name: global(moduix-collapsible-content-open-partial);
    }

    &[data-has-collapsed-size][data-state='closed'] {
      animation-name: global(moduix-collapsible-content-closed-partial);
    }
  }

  .body {
    display: grid;
    gap: var(--moduix-collapsible-body-gap, var(--moduix-spacing-2));
    min-width: 0;
    padding: var(--moduix-collapsible-body-padding, 0);
  }

  @media (prefers-reduced-motion: reduce) {
    .indicator {
      transition: none;
    }

    .content[data-state] {
      animation: none;
    }
  }
}
